 private JSONObject json(String key,Object value){try{return new JSONObject().put(key,value);}catch(Exception e){return new JSONObject();}}
 private String safe(Exception e){if(ConnectionDiagnostics.ssl(e)||ConnectionDiagnostics.plaintextTls(e))return l(ConnectionDiagnostics.tls(e));String m=e.getMessage();if(e instanceof SocketTimeoutException)return l("انتهت مهلة الاتصال بالسيرفر. جرّب مرة أخرى.");if(e instanceof UnknownHostException)return l("تعذر العثور على السيرفر. راجع الرابط والإنترنت.");if(m==null)return l("تعذر إكمال الاتصال");if(e instanceof org.json.JSONException)return tr("The server did not return valid JSON data.","السيرفر لم يرجع بيانات JSON صالحة.");return DiagnosticText.redact(l(m));}
 private void error(String message,String request){JSONObject j=json("message",message);try{j.put("request",request);}catch(Exception ignored){}emit("error",j);}
 private JSONObject find(String key){for(int i=0;i<accounts.length();i++){JSONObject p=accounts.optJSONObject(i);if(p!=null&&p.optString("key").equals(key))return p;}return null;}
 private void state(){try{JSONArray a=new JSONArray();for(int i=0;i<accounts.length();i++){JSONObject p=accounts.getJSONObject(i);a.put(new JSONObject().put("key",p.optString("key")).put("name",p.optString("name")).put("mode",p.optString("mode")));}emit("state",new JSONObject().put("accounts",a).put("selected",prefs().getString("selected","")).put("format",prefs().getString("format","auto")).put("agent",prefs().getString("agent","vlc")).put("updateRepository",updates.repository()).put("automaticUpdates",updates.automatic()).put("version","1.9.4").put("bufferProfile",BufferProfile.of(prefs().getString("bufferProfile","balanced")).id).put("lockedKinds",new JSONArray(parental.kinds())).put("parentalEnabled",parental.enabled()).put("parentalUnlocked",parental.unlocked()).put("openLastChannel",prefs().getBoolean("openLastChannel",false)).put("smartReconnect",prefs().getBoolean("smartReconnect",true)).put("pip",prefs().getBoolean("pip",true)).put("language",language()));}catch(Exception e){error(safe(e),"");}}
 private void persist()throws Exception{Vault.save(this,accounts.toString());}
 private String key(String kind,Provider.Item item){return kind+":"+(item.folder?"folder:":"item:")+item.id;}
